package io.github.rebrowser.system;

import android.app.Application;
import android.os.Looper;
import android.os.SystemClock;
import io.github.rebrowser.bootstrap.ComponentGate;
import io.github.rebrowser.core.TaskCoordinator;
import io.github.rebrowser.download.ResponseStreamWorker;
import java.io.*;
import java.nio.channels.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Canonical native existing-epoch APK stages only. Actual bulk stream EOF/length/SHA, private
 * 0600 create-new/force/no-overwrite hardlink publication, ownership/space/retained-node bounds.
 * Bytes/SHA do NOT establish trusted publisher, valid APK or installation completion. No paths
 * from IPC, root/key/dir seed, user-file deletion, sweeper, refetch, automatic installer or replay.
 * Unknown/expired stages stay bounded/retained (new opens denied), not falsely settled/deleted.
 * Actual Android/F2FS/provider/installer/power-loss paths need independent qualification. */
public final class ApkStagingStore {
    public static final long MAX_APK_BYTES=512L*1024*1024,MAX_RETAINED_BYTES=1024L*1024*1024;
    public static final class Stage {
        private final ApkStagingStore issuer;private final Path path;private final Object fileKey;private final long bytes,expires;private final byte[] digest;private boolean handoffAttempted;
        private Stage(ApkStagingStore issuer,Path path,Object fileKey,long bytes,byte[] digest,long expires){this.issuer=issuer;this.path=path;this.fileKey=fileKey;this.bytes=bytes;this.digest=digest;this.expires=expires;}
        public long byteCount(){issuer.requireStage(this);return bytes;}public byte[] originalSha256(){issuer.requireStage(this);return digest.clone();}
        /** Native package-manager inspection only, never an IPC/public path. */
        String nativeInspectionPath()throws IOException{issuer.requireStage(this);issuer.requireFile(this);return path.toString();}
    }
    static final class ReadLease {
        final ApkStagingStore issuer;final Stage stage;final String token;final long expires;int openAttempts;
        ReadLease(ApkStagingStore issuer,Stage stage,String token,long expires){this.issuer=issuer;this.stage=stage;this.token=token;this.expires=expires;}
    }
    private final ComponentGate.DataEpochPin source;private final Path[] directories;private final Object[] keys;private final Path root;private final SecureRandom random=new SecureRandom();private final AtomicBoolean writing=new AtomicBoolean();private final Set<Stage> stages=Collections.newSetFromMap(new IdentityHashMap<Stage,Boolean>());private final Map<String,ReadLease> leases=new HashMap<>();private long last=-1;private volatile boolean retired;private volatile boolean unknownDescriptorClose;
    private ApkStagingStore(ComponentGate.DataEpochPin source,Path[] directories)throws IOException{this.source=source;this.directories=directories;root=directories[directories.length-1];keys=new Object[directories.length];for(int i=0;i<directories.length;i++){BasicFileAttributes a=attrs(directories[i]);if(!a.isDirectory() || a.fileKey()==null)throw new IOException("Existing identifiable private APK directories required");keys[i]=a.fileKey();}}
    public static ApkStagingStore openExisting(Application actualOwnApplication,ComponentGate.DataEpochPin actualSource)throws IOException{if(actualOwnApplication==null || actualSource==null)throw new IllegalArgumentException("Native APK source required");io();actualSource.requireCurrent();Path base=actualOwnApplication.getDataDir().toPath().resolve("no_backup"),epochs=base.resolve("owned-epochs-v1"),epoch=epochs.resolve(hex(actualSource.dataEpoch())),root=epoch.resolve("apk-staging-v1");ApkStagingStore store=new ApkStagingStore(actualSource,new Path[]{base,epochs,epoch,root});store.requireDirectories();return store;}
    /** Input ownership transfers on entry. Actual task must already have committed durable
     * dispatch intent; route is spent before stage/stream effects, never retried after unknown. */
    public Stage stageNativeOwnedInput(TaskCoordinator.Owner nativeTask,InputStream nativeOwnedInput,long expectedBytes,byte[] nativeExpectedSha256)throws IOException{
        io();if(nativeOwnedInput==null)throw new IllegalArgumentException("Native APK input required");try(InputStream owned=new FilterInputStream(nativeOwnedInput){private boolean closed;@Override public void close()throws IOException{if(closed)return;closed=true;super.close();}}){if(nativeTask==null || expectedBytes<1 || expectedBytes>MAX_APK_BYTES || nativeExpectedSha256==null || nativeExpectedSha256.length!=32)throw new IllegalArgumentException("Exact native APK source length/SHA required");byte[] expected=nativeExpectedSha256.clone();if(!writing.compareAndSet(false,true))throw new IOException("Native APK IO already owned");try{source.requireCurrent();final Object route=new Object();nativeTask.requireNativeDataSource(source);nativeTask.claimCommittedNativeRoute(route);nativeTask.requireCurrentCommittedNativeRoute(route);if(!nativeTask.mayPublishCurrentResult())throw new SecurityException("Native APK task fenced");String id=token();Path pending=root.resolve(id+".pending"),target=root.resolve(id+".apk");requireDirectories();try(Locked ignored=lock()){admit(expectedBytes);ResponseStreamWorker.CopiedStage copied;
                try(FileChannel file=FileChannel.open(pending,Set.of(StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS),PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rw-------")))){
                    OutputStream privateOutput=new OutputStream(){boolean closed;final OutputStream stream=Channels.newOutputStream(file);public void write(int b)throws IOException{throw new IOException("Bulk-only native stage");}public void write(byte[] b,int off,int n)throws IOException{source.requireCurrent();nativeTask.requireCurrentCommittedNativeRoute(route);stream.write(b,off,n);}public void flush()throws IOException{file.force(true);}public void close()throws IOException{if(closed)return;closed=true;try{file.force(true);}finally{file.close();}}};
                    // Non-closing input proxy: this method owns ONE actual input close, before publication.
                    InputStream borrowed=new FilterInputStream(owned){@Override public void close(){}};
                    copied=ResponseStreamWorker.copyOwned(borrowed,privateOutput,MAX_APK_BYTES,expectedBytes,nativeTask.cancellation());
                }
                if(!MessageDigest.isEqual(copied.originalSha256(),expected))throw new IOException("Native APK source digest mismatch");
                owned.close(); // Actual body close must return before any usable Stage is issued.
                nativeTask.requireCurrentCommittedNativeRoute(route);requireDirectories();BasicFileAttributes a=attrs(pending);if(!a.isRegularFile() || a.fileKey()==null || a.size()!=copied.byteCount())throw new IOException("Native APK stage changed");verifyReadback(pending,a.size(),expected,nativeTask,route);if(!a.fileKey().equals(attrs(pending).fileKey()))throw new IOException("Native APK stage replaced during readback");Files.createLink(target,pending);forceDirectory();if(!a.fileKey().equals(attrs(target).fileKey()) || !a.fileKey().equals(attrs(pending).fileKey()))throw new IOException("Native APK immutable publication changed");Files.delete(pending);forceDirectory();requireDirectories();nativeTask.requireCurrentCommittedNativeRoute(route);long now=now();if(now>Long.MAX_VALUE-30*60_000)throw new IOException("Native APK clock exhausted");Stage stage=new Stage(this,target,a.fileKey(),a.size(),copied.originalSha256(),now+30*60_000);synchronized(this){if(stages.size()>=8)throw new IOException("Native APK retained stage budget reached");stages.add(stage);}return stage;
            }}finally{writing.set(false);}} // Failure may leave owned pending/final bytes; never deletes/retries an unknown handoff.
    }
    void requireOwnedStageForNativePreparation(Stage stage)throws IOException{requireStage(stage);requireFile(stage);}
    synchronized void requireUnexpiredHandoffLease(ReadLease exact){long value=now();if(exact==null || exact.issuer!=this || leases.get(exact.token)!=exact || value>=exact.expires)throw new SecurityException("Native APK handoff lease retired/expired");requireStage(exact.stage);}
    synchronized ReadLease spendForNativeHandoff(Stage stage)throws IOException{requireStage(stage);requireFile(stage);if(stage.handoffAttempted || leases.size()>=16)throw new SecurityException("Native APK handoff unavailable or spent");stage.handoffAttempted=true;long now=now();if(now>Long.MAX_VALUE-120_000)throw new IOException("Native APK clock exhausted");String token=token();if(leases.containsKey(token))throw new IOException("Native APK lease collision");ReadLease lease=new ReadLease(this,stage,token,Math.min(stage.expires,now+120_000));leases.put(token,lease);return lease;}
    synchronized ReadLease resolveNativeReadToken(String exactToken)throws IOException{long now=now();if(exactToken==null || !exactToken.matches("[0-9a-f]{64}"))throw new SecurityException("Native APK URI unavailable");ReadLease lease=leases.get(exactToken);if(lease==null || lease.expires<=now)throw new SecurityException("Native APK URI expired/unavailable");requireStage(lease.stage);requireFile(lease.stage);return lease;}
    android.os.ParcelFileDescriptor openGrantedNativeToken(String token)throws IOException{ReadLease lease=resolveNativeReadToken(token);synchronized(lease){if(lease.openAttempts>=4)throw new IOException("Native APK URI open budget reached");lease.openAttempts++;}java.io.FileDescriptor nativeFd;try{nativeFd=android.system.Os.open(lease.stage.path.toString(),android.system.OsConstants.O_RDONLY|android.system.OsConstants.O_NOFOLLOW|android.system.OsConstants.O_CLOEXEC,0);}catch(android.system.ErrnoException rejected){throw new IOException("Native APK source open unavailable",rejected);}android.os.ParcelFileDescriptor descriptor=null;boolean closeAttempted=false,issued=false;try{descriptor=android.os.ParcelFileDescriptor.dup(nativeFd);resolveNativeReadToken(token);closeAttempted=true;try{android.system.Os.close(nativeFd);}catch(android.system.ErrnoException unknown){unknownDescriptorClose=true;throw new IOException("Native APK descriptor settlement unknown",unknown);}issued=true;return descriptor;}finally{if(!closeAttempted)try{android.system.Os.close(nativeFd);}catch(android.system.ErrnoException unknown){unknownDescriptorClose=true;}if(!issued && descriptor!=null)try{descriptor.close();}catch(IOException unknown){unknownDescriptorClose=true;}}}
    public boolean hasUnknownNativeDescriptorClose(){return unknownDescriptorClose;}
    public void requireBindings(ComponentGate expectedGate,ComponentGate.BusinessPermit permit){source.requireBindings(expectedGate,permit);}
    public synchronized void retireNewReads(){retired=true;} // Existing OS descriptors/work may still be alive; not a delete/end receipt.
    private synchronized void requireStage(Stage stage){long now=now();if(stage==null || stage.issuer!=this || !stages.contains(stage) || now>=stage.expires)throw new SecurityException("Native APK stage retired/expired");}
    private void requireFile(Stage stage)throws IOException{requireDirectories();BasicFileAttributes a=attrs(stage.path);if(!a.isRegularFile() || !stage.fileKey.equals(a.fileKey()) || a.size()!=stage.bytes)throw new IOException("Native APK stage no longer exact");}
    private void admit(long bytes)throws IOException{requireDirectories();long total=0;int count=0;Set<String> objects=new HashSet<>();try(DirectoryStream<Path> entries=Files.newDirectoryStream(root)){for(Path p:entries){if(++count>17)throw new IOException("Native APK retained node budget reached");BasicFileAttributes a=attrs(p);String name=p.getFileName().toString();if(!a.isRegularFile() || a.fileKey()==null)throw new IOException("Unknown native APK node");if(name.equals(".apk.lock")){if(a.size()!=0)throw new IOException("Unsafe native APK lock");continue;}if(!name.matches("[0-9a-f]{64}\\.(apk|pending)") || a.size()<0 || a.size()>MAX_RETAINED_BYTES-total)throw new IOException("Unknown/oversized native APK node");objects.add(name.substring(0,64));total+=a.size();}}if(objects.size()>=8 || count>15 || bytes>MAX_RETAINED_BYTES-total)throw new IOException("Native APK retained storage budget reached");}
    private Locked lock()throws IOException{Path p=root.resolve(".apk.lock");try(FileChannel ignored=FileChannel.open(p,Set.of(StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS),PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rw-------")))){}catch(FileAlreadyExistsException exists){}BasicFileAttributes a=attrs(p);if(!a.isRegularFile() || a.size()!=0 || a.fileKey()==null)throw new IOException("Unsafe native APK lock");FileChannel channel=FileChannel.open(p,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);FileLock held=null;try{try{held=channel.tryLock();}catch(OverlappingFileLockException busy){throw new IOException("Native APK writer busy");}if(held==null || !a.fileKey().equals(attrs(p).fileKey()))throw new IOException("Native APK lock unavailable");return new Locked(channel,held);}catch(IOException|RuntimeException failure){if(held!=null)held.release();channel.close();throw failure;}}
    private static final class Locked implements AutoCloseable{final FileChannel channel;final FileLock lock;Locked(FileChannel c,FileLock l){channel=c;lock=l;}public void close()throws IOException{try{lock.release();}finally{channel.close();}}}
    private void requireDirectories()throws IOException{source.requireCurrent();if(retired)throw new SecurityException("Native APK store retired");for(int i=0;i<directories.length;i++){BasicFileAttributes a=attrs(directories[i]);if(!a.isDirectory() || !keys[i].equals(a.fileKey()))throw new IOException("Native APK directory replaced");}}
    private synchronized long now(){source.requireCurrent();long value=SystemClock.elapsedRealtime();if(retired || value<0 || value<last){retired=true;throw new SecurityException("Native APK clock/source retired");}last=value;return value;}
    private void verifyReadback(Path file,long expectedBytes,byte[] expectedDigest,TaskCoordinator.Owner owner,Object exactRoute)throws IOException{MessageDigest digest;try{digest=MessageDigest.getInstance("SHA-256");}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}byte[] buffer=new byte[32768];long total=0;try(InputStream in=Channels.newInputStream(FileChannel.open(file,StandardOpenOption.READ,LinkOption.NOFOLLOW_LINKS))){for(;;){source.requireCurrent();owner.requireCurrentCommittedNativeRoute(exactRoute);if(owner.cancellation().snapshot().cancellationRequested())throw new IOException("Native APK readback fenced/cancelled");int n=in.read(buffer,0,(int)Math.min(buffer.length,expectedBytes-total+1));if(n<0)break;if(n<=0 || n>expectedBytes-total)throw new IOException("Native APK readback size/progress changed");digest.update(buffer,0,n);total+=n;}if(total!=expectedBytes || !MessageDigest.isEqual(digest.digest(),expectedDigest))throw new IOException("Native APK readback digest changed");}finally{Arrays.fill(buffer,(byte)0);}}
    private String token(){byte[] b=new byte[32];random.nextBytes(b);return hex(b);}
    private static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(Character.forDigit((v&255)>>>4,16)).append(Character.forDigit(v&15,16));return s.toString();}
    private static BasicFileAttributes attrs(Path p)throws IOException{return Files.readAttributes(p,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);}
    private void forceDirectory()throws IOException{try(FileChannel directory=FileChannel.open(root,StandardOpenOption.READ)){directory.force(true);}}
    private static void io(){if(Looper.myLooper()==Looper.getMainLooper())throw new IllegalStateException("Native APK bounded IO owner required");}
}
